// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Create a simple token that implements transferFrom
        // We'll deploy a minimal token contract inline
        // The token must be able to receive the call and revert if parameters are wrong
        Token token = new Token();

        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;

        // The reference contract will call transferFrom(from, tos[0], vals[0]) and succeed
        // The buggy contract will call approve(from, tos[0]) with wrong signature and revert

        // We need to test that c.transfer returns true (reference) and would fail in buggy version
        bool result;
        try c.transfer(address(this), address(token), tos, vals) {
            result = true;
        } catch {
            result = false;
        }

        // The reference should succeed (transferFrom shall pass), but the buggy tries approve and fails
        assertTrue(result == true, "Reference should succeed, bug should fail");
    }
}

contract Token {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(amount > 0, "Amount must be positive");
        allowance[from][msg.sender] -= amount;
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token contract that will fail the second transferFrom call
        // so that the reference will revert and the bug will silently continue.
        FailingToken token = new FailingToken();
        address tokenAddr = address(token);

        // Prepare addresses
        address from = address(0x1);
        address to1 = address(0x2);
        address to2 = address(0x3);

        // Call transfer with two recipients and values
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;

        uint[] memory vals = new uint[](2);
        vals[0] = 10;
        vals[1] = 20;

        // Attempt to call c.transfer (the public entry point)
        // For the reference, this will revert because the second call fails and require(_s) reverts.
        // For the bug, call will succeed silently and return true.
        // We catch the revert and check the boolean outcome.
        bool ok;
        try c.transfer(from, tokenAddr, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract reverts (ok == false) because require on the inner call fails.
        // The buggy version returns true (ok == true).
        // We assert that ok == false, which holds for the reference and fails for the bug.
        assertTrue(!ok, "Reference should revert on failing inner call");
    }
}

// Token contract that fails on the second transferFrom call
contract FailingToken {
    uint256 callCount;
    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        if (callCount == 2) {
            return false;
        }
        return true;
    }
}

