pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like contract that will fail on the second transferFrom
        address token = address(new Token());
        address from = address(0x1);
        address[] memory tos = new address[](2);
        tos[0] = address(0x2);
        tos[1] = address(0x3);
        uint[] memory vals = new uint[](2);
        vals[0] = 10;
        vals[1] = 20;

        bool ok;
        try c.transfer(from, token, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}

contract Token {
    uint256 public failCount = 0;
    function transferFrom(address, address, uint256) external returns (bool) {
        failCount++;
        if (failCount == 2) {
            return false;
        }
        return true;
    }
}
